"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0db/refs"
import { useFormReset } from "@/lib/0db/use-form-reset"
import { cn } from "@/lib/utils"

type AllocationItem = { id: string; label: string; disabled?: boolean }
type AllocationProps = Omit<React.ComponentProps<"fieldset">, "children" | "onChange" | "defaultValue"> & {
  label: React.ReactNode
  items: AllocationItem[]
  total: number
  value?: Record<string, number>
  defaultValue?: Record<string, number>
  onValueChange?: (value: Record<string, number>) => void
  step?: number
  unit?: string
  name?: string
  remainingLabel?: string
  excessLabel?: string
  format?: (value: number) => string
}

const numbers = new Intl.NumberFormat("en-GB", { maximumFractionDigits: 4 })
/** Set several shares of one finite allowance. Unassigned space remains explicit; changing one never edits another. */
function Allocation({ label, items, total, value: controlled, defaultValue = {}, onValueChange, step = 1, unit = "", name, remainingLabel = "Unassigned", excessLabel = "Over allowance", format = (n) => numbers.format(n), disabled, form, className, ref: forwardedRef, ...props }: AllocationProps) {
  const id = React.useId()
  const [local, setLocal] = React.useState(defaultValue)
  const root = React.useRef<HTMLFieldSetElement>(null)
  const ref = useComposedRefs(root, forwardedRef)
  useFormReset(root, () => { if (controlled === undefined) setLocal(defaultValue) })
  const raw = controlled ?? local
  const value = Object.fromEntries(items.map((item) => [item.id, Object.hasOwn(raw, item.id) ? raw[item.id] : 0]))
  if (!Number.isFinite(total) || total < 0 || !Number.isFinite(step) || step <= 0 || new Set(items.map((item) => item.id)).size !== items.length || items.some((item) => !item.id || !Number.isFinite(value[item.id]) || value[item.id] < 0))
    throw new RangeError("Allocation needs unique ids, finite non-negative shares and total, and a positive step")
  const sum = Object.values(value).reduce((a, b) => a + b, 0)
  if (!Number.isFinite(sum)) throw new RangeError("Allocation shares overflow the finite allowance")
  const tolerance = Number.EPSILON * Math.max(total, sum) * Math.max(1, items.length) * 2
  const clean = (n: number) => Math.abs(n) <= tolerance ? 0 : Number(n.toPrecision(12))
  const remaining = clean(total - sum)
  const over = remaining < 0
  const [previous, setPrevious] = React.useState(remaining)
  const [acted, setActed] = React.useState(false)
  if (previous !== remaining) { setPrevious(remaining); setActed(true) }
  return <fieldset {...props} ref={ref} form={form} disabled={disabled} data-slot="allocation" data-acted={acted ? "" : undefined} className={cn("db-allocation", className)} aria-invalid={over || undefined}>
    <legend data-slot="allocation-label">{label}</legend>
    <div data-slot="allocation-balance" className="db-allocation-balance" data-invalid={over ? "" : undefined}>
      <span aria-hidden="true">{over ? excessLabel : remainingLabel}</span><output id={`${id}-balance`} aria-live="polite"><span className="db-sr">{over ? excessLabel : remainingLabel}: </span><bdi key={remaining} dir="ltr" className="db-yours">{format(Math.abs(remaining))}</bdi><small>{unit}</small></output>
    </div>
    <div data-slot="allocation-shares" className="db-allocation-shares">
      {items.map((item) => <div key={item.id} data-slot="allocation-share" className="db-allocation-share">
        <label htmlFor={`${id}-${item.id}`}>{item.label}</label>
        <input data-slot="allocation-input" id={`${id}-${item.id}`} type="number" min={0} max={Math.max(0, clean(total - (sum - value[item.id])))} step={step} form={form} name={name ? `${name}[${item.id}]` : undefined} value={value[item.id]} disabled={disabled || item.disabled} aria-describedby={`${id}-balance`} aria-invalid={over || undefined} onChange={(e) => {
          const n = e.target.value === "" ? 0 : e.target.valueAsNumber
          if (!Number.isFinite(n)) return
          const limit = Math.max(0, clean(total - (sum - value[item.id])))
          const next = { ...value, [item.id]: Math.min(limit, Math.max(0, n)) }
          if (controlled === undefined) setLocal(next)
          onValueChange?.(next)
        }} />
        <span className="db-allocation-dimension" aria-hidden="true" style={{ "--db-allocation-share": total ? Math.min(1, value[item.id] / total) : 0 } as React.CSSProperties} />
      </div>)}
    </div>
  </fieldset>
}

export { Allocation, type AllocationProps, type AllocationItem }

@layer components {
  /* A balance with three independent arms: unused time is a figure, the shares are travelling dimensions. */
  .db-allocation { min-inline-size: 0; padding: 0; border: 0; overflow-wrap: anywhere; container-type: inline-size; }
  .db-allocation > legend { font-size: var(--db-pp); padding: 0; color: var(--db-graphite); }
  .db-allocation-balance { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: var(--db-space-3); margin-block: var(--db-space-5) var(--db-space-6); padding-block-end: var(--db-space-4); border-block-end: var(--db-hairline) solid var(--db-rule); }
  .db-allocation-balance > span { font-size: var(--db-pp); color: var(--db-pencil); }
  .db-allocation-balance output { font-size: clamp(4rem, 20cqi, 8rem); line-height: 1; letter-spacing: -0.06em; color: var(--db-ink); overflow-wrap: anywhere; }
  .db-allocation-balance output small { font-size: var(--db-pp); font-family: var(--db-voice); white-space: pre-wrap; margin-inline-start: var(--db-space-2); letter-spacing: 0; }
  .db-allocation-balance[data-invalid] output { color: var(--db-signal); }
  .db-allocation-shares { display: grid; gap: var(--db-space-5); counter-reset: db-share; }
  .db-allocation-share { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) minmax(4ch, 5ch); align-items: baseline; column-gap: var(--db-space-4); counter-increment: db-share; padding-inline-start: 2rem; }
  .db-allocation-share::before { content: counter(db-share, decimal-leading-zero); position: absolute; inset-inline-start: 0; inset-block-start: 0.5rem; font-size: var(--db-pp); color: var(--db-pencil); }
  .db-allocation-share > label { font-size: clamp(1.2rem, 4.5cqi, 1.8rem); font-weight: 300; }
  .db-allocation-share input { min-inline-size: 0; inline-size: 100%; border: 0; background: none; font-family: var(--db-expression); font-style: italic; font-size: clamp(1.8rem, 7cqi, 3rem); line-height: 1; color: var(--db-ink); padding-block: var(--db-space-2); padding-inline: 0; font-variant-numeric: tabular-nums; text-align: end; appearance: textfield; }
  .db-allocation-share input::-webkit-inner-spin-button, .db-allocation-share input::-webkit-outer-spin-button { appearance: none; margin: 0; }
  .db-allocation-dimension { --db-allocation-share: 0; grid-column: 1 / -1; position: relative; display: block; inline-size: calc(var(--db-allocation-share) * 100%); block-size: 1.25rem; border-block-end: var(--db-hairline) solid var(--db-rule-strong); border-inline-end: var(--db-hairline) solid var(--db-ink); margin-block-start: var(--db-space-2); transition: inline-size var(--db-andante) var(--db-spiccato), block-size var(--db-andante) var(--db-exhale); }
  .db-allocation-dimension::before { content: ""; position: absolute; inset-inline-start: 0; inset-block-end: 0; block-size: 0.4rem; border-inline-start: var(--db-hairline) solid var(--db-rule-strong); }
  .db-allocation-share:focus-within .db-allocation-dimension { block-size: 2.5rem; border-color: var(--db-accent); }
  .db-allocation input:disabled { color: var(--db-pencil); }
  .db-allocation[data-acted] .db-allocation-balance bdi { display: inline-block; transform-origin: right bottom; animation: db-allocation-counterweight var(--db-andante) var(--db-spiccato); }
  @keyframes db-allocation-counterweight { 0% { transform: rotate(-4deg) skewX(-6deg) scaleX(0.9); } 65% { transform: rotate(0.7deg) skewX(1deg) scaleX(1.02); } 100% { transform: none; } }
  @media (prefers-reduced-motion: reduce) { .db-allocation-dimension, .db-allocation[data-acted] .db-allocation-balance bdi { transition: none; animation: none; } }
}
